  const hGalIdx={};
  function hGalNav(pid,dir){const imgs=hGalleries[pid];if(!imgs||!imgs.length)return;hGalIdx[pid]=((hGalIdx[pid]||0)+dir+imgs.length)%imgs.length;hGalSet(pid,hGalIdx[pid]);}
  function hGalSet(pid,idx){const imgs=hGalleries[pid];hGalIdx[pid]=idx;document.getElementById('hmain-'+pid).src=imgs[idx];document.getElementById('hctr-'+pid).textContent=(idx+1)+' / '+imgs.length;const thumbs=document.getElementById('hthumbs-'+pid).querySelectorAll('.h-thumb');thumbs.forEach((t,i)=>t.classList.toggle('h-thumb-active',i===idx));}
  const hTopIds=["vorstadt1", "vorstadt9", "luitpoldstr2og", "fabrikzeile48_2og", "schutzenstr"];
  const hVacantIds=["vorstadt1", "fabrikzeile48_2og", "alsenbergerstr9", "schutzenstr", "munsterstr3", "wunsiedler", "weissenburg", "westendstrEG"];
  const hSkipIds=["oelsniterlinks", "westendstrEG", "oberestor", "luitpoldstr1og"];
  const hBudgetIds=["vorstadt1", "vorstadt9", "luitpoldstr2og", "fabrikzeile48_2og", "fabrikzeile48_1og", "alsenbergerstr9", "auguststr9", "fabrikzeile46", "ottostr2og", "schutzenstr", "munsterstr3", "munsterstr4", "munsterstr5", "weissenburg", "luitpoldstr1og"];
  const hFilterMap={
    all:()=>true,
    best:id=>hTopIds.includes(id),
    vacant:id=>hVacantIds.includes(id),
    budget:id=>hBudgetIds.includes(id),
    skip:id=>hSkipIds.includes(id),
  };
  function hFilter(type,btn){document.querySelectorAll('.h-filter-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.h-card').forEach(card=>{const id=card.id.replace('hcard-','');card.style.display=hFilterMap[type](id)?'':'none';});}

// ═══════════════ HOUSING ROOMS LAZY LOADER ═══════════════
let housingRoomsLoaded = false;

async function loadHousingRooms() {
  if (housingRoomsLoaded) return;
  try {
    const res = await fetch('tabs/housing-rooms.html');
    const html = await res.text();
    const container = document.getElementById('tab-housing-rooms');
    if (container) {
      container.innerHTML = html
        .replace('<div id="tab-housing-rooms" class="section">', '')
        .replace(/^<div id="tab-housing-rooms"[^>]*>/, '')
        .trimStart();
      // Remove the last closing </div> that belonged to the outer tab wrapper
      housingRoomsLoaded = true;
    }
  } catch(e) {
    console.error('Failed to load housing rooms:', e);
  }
}
